import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and statistical significance
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            t_stat = feats.x[:, i].T @ (feats.y * 2 - 1) / (np.std(feats.x[:, i]) * np.sqrt(len(feats.y)))
            if abs(t_stat) > 2.0:
                candidates.append((fid, abs(t_stat)))

    # Sort by t-statistic magnitude
    candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    keep = []
    excluded = set()
    for fid, _ in candidates:
        if fid in excluded:
            continue
        keep.append(fid)
        # Find correlated features to exclude
        for other_fid in feats.ids:
            if other_fid != fid and other_fid not in excluded:
                idx1 = feats.column(fid)
                idx2 = feats.column(other_fid)
                corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
                if abs(corr) >= 0.6:
                    excluded.add(other_fid)
        if len(keep) >= MAX_DRIVERS:
            break

    # If no strong candidates found, return empty design
    if not keep:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Limit to at most 4 drivers as per checker report
    drivers = tuple(keep[:4])
    columns = tuple(keep)

    # Add interaction terms for top two drivers if they exist
    products = ()
    if len(drivers) >= 2:
        products = ((drivers[0], drivers[1]),)

    # Weighted score: sum of standardized features with positive coefficients
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        # Use effect size as weight
        effect = np.mean(feats.x[feats.y==1, idx]) - np.mean(feats.x[feats.y==0, idx])
        loadings[fid] = effect

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

